import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiMobs","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/mobs/index.md","filePath":"en/modules/mobs/index.md","lastUpdated":0}`),a={name:`en/modules/mobs/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakimobs" tabindex="-1">EmakiMobs <a class="header-anchor" href="#emakimobs" aria-label="Permalink to “EmakiMobs”">​</a></h1><p>EmakiMobs is the custom mob system module. It lets server administrators define custom mobs with YAML, configure spawn rules, loot tables, and skill behaviors, with deep integration into EmakiAttribute, EmakiSkills, and EmakiItem.</p><h2 id="module-facts" tabindex="-1">Module facts <a class="header-anchor" href="#module-facts" aria-label="Permalink to “Module facts”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.0.0</code></td></tr><tr><td>Main command</td><td><code>/emakimobs</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependencies</td><td>EmakiAttribute, EmakiSkills, EmakiItem, PlaceholderAPI</td></tr><tr><td>Permissions</td><td><code>emakimobs.use</code>, <code>emakimobs.spawn</code>, <code>emakimobs.reload</code>, <code>emakimobs.debug</code>, <code>emakimobs.admin</code></td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Spawning custom mobs and reloading configuration.</td></tr><tr><td><a href="./definitions.html">Definitions</a></td><td>Full field reference for <code>mobs/*.yml</code>, including components, attributes, skills, threat table, and boss bar.</td></tr><tr><td><a href="./components.html">Components</a></td><td>All component fields supported by ComponentMapper.</td></tr><tr><td><a href="./spawn-rules.html">Spawn Rules</a></td><td>Full field reference for <code>spawn_rules/*.yml</code>, covering the <code>natural</code> and <code>autonomous</code> types.</td></tr><tr><td><a href="./loot-tables.html">Loot Tables</a></td><td>Pool, entry, and function configuration in <code>loot_tables/*.yml</code>.</td></tr><tr><td><a href="./triggers.html">Triggers</a></td><td>Mob trigger list and action context variables.</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core capabilities”">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>Custom mob definitions</td><td>YAML-driven mob type, stats, appearance, and behavior; hot-reloaded.</td></tr><tr><td>Type override</td><td>When <code>id</code> matches a vanilla EntityType name, the config is applied to all naturally spawned entities of that type.</td></tr><tr><td>Two spawn strategies</td><td><code>natural</code> intercepts vanilla spawn events; <code>autonomous</code> runs on its own scheduler (<code>interval</code> / <code>player_follow</code> / <code>day_interval</code> / <code>cron</code> triggers).</td></tr><tr><td>Loot table system</td><td>Multi-pool, weighted entries with count functions and looting enchant bonus.</td></tr><tr><td>EmakiItem integration</td><td>Loot table entries drop EmakiItem items through the <code>emaki_item</code> key.</td></tr><tr><td>EmakiAttribute integration</td><td><code>attributes</code> section writes EA attribute values directly onto the mob.</td></tr><tr><td>Skill triggers</td><td>Eleven lifecycle events fire CoreLib action pipelines.</td></tr><tr><td>Threat table</td><td>Sorts targets by accumulated threat; supports custom weights and decay.</td></tr><tr><td>Boss bar</td><td>Shows mob health to players within range; configurable color and style.</td></tr></tbody></table><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to “Default runtime folder”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiMobs/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── mobs/               ← mob definition files</span></span>
<span class="line"><span>├── loot_tables/        ← loot table files</span></span>
<span class="line"><span>├── spawn_rules/        ← spawn rule files</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>mobs/</code> defines mobs, <code>loot_tables/</code> defines drops, and <code>spawn_rules/</code> defines when and where mobs appear. Any <code>.yml</code> file placed in these directories takes effect after <code>/emakimobs reload</code>.</p><h2 id="main-configuration" tabindex="-1">Main configuration <a class="header-anchor" href="#main-configuration" aria-label="Permalink to “Main configuration”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>Current version</td><td>Config structure marker; manual edits are discouraged.</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>Language file ID, matching <code>lang/&lt;language&gt;.yml</code>.</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>Whether to release example files in <code>mobs/</code>, <code>loot_tables/</code>, and <code>spawn_rules/</code> on first start.</td></tr><tr><td><code>drain_timeout_seconds</code></td><td>int</td><td><code>30</code></td><td>Seconds to wait for in-flight tasks before completing a reload.</td></tr></tbody></table><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to “Typical workflow”">​</a></h2><ol><li>Create a mob definition in <code>mobs/</code> with an id, entity type, and component values.</li><li>Create a matching loot table in <code>loot_tables/</code> with a <code>mob_id</code> matching the mob id.</li><li>Add a spawn rule in <code>spawn_rules/</code> to link the mob to spawn conditions.</li><li>Run <code>/emakimobs reload</code> or restart the server.</li><li>Use <code>/emakimobs spawn &lt;mob_id&gt;</code> to test the mob at your current location.</li></ol><h2 id="relations-with-other-modules" tabindex="-1">Relations with other modules <a class="header-anchor" href="#relations-with-other-modules" aria-label="Permalink to “Relations with other modules”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Integration</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>The <code>attributes</code> section in mob definitions writes EA attribute values onto spawned entities.</td></tr><tr><td>EmakiSkills</td><td>The <code>skills</code> section fires CoreLib action pipelines on lifecycle trigger events.</td></tr><tr><td>EmakiItem</td><td>Loot table entries name an EmakiItem item ID under the <code>emaki_item</code> key to drop custom items.</td></tr><tr><td>EmakiCoreLib</td><td>Provides the action pipeline engine for skills and the plugin lifecycle infrastructure.</td></tr></tbody></table>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};